function maxDepth(tokens) {
  // BUG: increments depth, then records max AFTER also processing a close on
  // the same step pattern, so the peak (right at the deepest open) is missed.
  let depth = 0;
  let max = 0;
  for (const t of tokens) {
    if (t === '[') {
      depth++;
    } else if (t === ']') {
      depth--;
      if (depth > max) max = depth;
    }
  }
  return max;
}

